 void fetch(){if(api.isEmpty())return;loading=true;render();String d=date();new Thread(()->{try{URL u=new URL("https://v3.football.api-sports.io/fixtures?date="+d+"&timezone=Asia%2FRiyadh");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setRequestProperty("x-apisports-key",api);c.setConnectTimeout(12000);c.setReadTimeout(15000);int http=c.getResponseCode();if(http!=200)throw new Exception("HTTP "+http);ByteArrayOutputStream b=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))!=-1)b.write(bytes,0,n);}JSONObject json=new JSONObject(b.toString("UTF-8"));JSONArray result=json.optJSONArray("response");if(result==null)throw new Exception("API response");runOnUiThread(()->{cache=result;loading=false;render();});}catch(Exception ex){runOnUiThread(()->{loading=false;container.removeAllViews();empty("تعذر تحميل النتائج. تحقق من الإنترنت أو مفتاح API.");});}}).start();}
